import java.util.Scanner;

public class Main {
    static final int MAXNODES = 1000010;
    static final long MOD_VAL = 1000000007;
    static long total_p, factor_k, total_ans = 1;
    static int[] visited_marker = new int[MAXNODES];
    static int[] cycle_freq = new int[MAXNODES];

    static void dfs_traverse(int node, int depth) {
        if (visited_marker[node] == 1) {
            cycle_freq[depth]++;
            return;
        }
        visited_marker[node] = 1;
        long next_node = (node * factor_k) % total_p;
        dfs_traverse((int) next_node, depth + 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_p = sc.nextLong();
        factor_k = sc.nextLong();

        if (factor_k != 0 && factor_k != 1) {
            for (int i = 1; i < total_p; i++) {
                if (visited_marker[i] == 0) {
                    dfs_traverse(i, 0);
                }
            }
            for (int i = 1; i <= total_p; i++) {
                for (int j = 1; j <= cycle_freq[i]; j++) {
                    total_ans = (total_ans * (cycle_freq[i] * i + 1)) % MOD_VAL;
                }
            }
        } else if (factor_k == 0) {
            for (int i = 1; i < total_p; i++) {
                total_ans = (total_ans * total_p) % MOD_VAL;
            }
        } else if (factor_k == 1) {
            for (int i = 1; i <= total_p; i++) {
                total_ans = (total_ans * total_p) % MOD_VAL;
            }
        }
        System.out.println(total_ans);
        sc.close();
    }
}

